// One CTA computes: one batch item, one 16-wide output-channel tile inside one group,
// and one 16x16 output spatial tile. Input-channel accumulation is chunked by 16.
__global__ void conv2d_cute_tiled_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
