    }

    __syncthreads();

    if (valid_p) {
      const int ih_base_l = oh_l * stride;
      const int iw_base_l = ow_l * stride;

      if (KH == 3 && KW == 3) {
        const int x_row_base = ih_base_l * SW + iw_base_l;
