          for (int kw = 0; kw < 3; ++kw) {
            const int x_off = x_hoff + kw * dilation;
            const int w_koff = kh * 3 + kw;
            #pragma unroll
            for (int ic_l = 0; ic_l < IC_T; ++ic_l) {
              const float xv = sX_ptr[ic_l * x_cstride + x_off];
              const int w_base = ic_l * 9 + w_koff;
              #pragma unroll
              for (int oc_l = 0; oc_l < OC_T; ++oc_l) {
                acc[oc_l] += xv * sW_ptr[oc_l * (IC_T * 9) + w_base];
              }
            }
          }
        }
      } else {
        for (int kh = 0; kh < KH; ++kh) {
          const int ih_l = ih_base_l + kh * dilation;
          for (int kw = 0; kw < KW; ++kw) {
            const int iw_l = iw_base_l + kw * dilation;
            #pragma unroll
            for (int ic_l = 0; ic_l < IC_T; ++ic_l) {
              const float xv = (float)sX(ic_l, ih_l, iw_l);
              #pragma unroll
              for (int oc_l = 0; oc_l < OC_T; ++oc_l) {
