  const int oc_t = blockIdx.y % tiles_oc_per_group;

  const int oh0 = oh_t * OH_T;
  const int ow0 = ow_t * OW_T;

  const int oc_group_start = g * out_per_group;
  const int oc_group_end   = oc_group_start + out_per_group;
  const int oc0 = oc_group_start + oc_t * OC_T;
  const int oc_end = min(oc0 + OC_T, oc_group_end);

  const int ic_base = g * in_per_group;

  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWo = (int64_t)in_per_group * KH * KW;
  const int64_t sWi = (int64_t)KH * KW;
  const int64_t sWh = (int64_t)KW;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, in_per_group, KH, KW),
      make_stride(sWo, sWi, sWh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  const int SH = (OH_T - 1) * stride + (KH - 1) * dilation + 1;
  const int SW = (OW_T - 1) * stride + (KW - 1) * dilation + 1;

  extern __shared__ float smem[];
  float* sX_ptr = smem;
  float* sW_ptr = smem + IC_T * SH * SW;

  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Int<IC_T>{}, SH, SW),
      make_stride(SH * SW, SW, Int<1>{})
  );

  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OC_T>{}, Int<IC_T>{}, KH, KW),
      make_stride(IC_T * KH * KW, KH * KW, KW, Int<1>{})
  );

  const int oh_l = tid / OW_T;
  const int ow_l = tid - oh_l * OW_T;
  const int oh = oh0 + oh_l;
  const int ow = ow0 + ow_l;
  const bool valid_p = (oh < Hout) && (ow < Wout);

  float acc[OC_T];
  #pragma unroll
  for (int oc_l = 0; oc_l < OC_T; ++oc_l) {
    const int oc = oc0 + oc_l;
    acc[oc_l] = (B != nullptr && oc < oc_end) ? (float)B[oc] : 0.0f;
  }

  const int base_ih = oh0 * stride - padding;
  const int base_iw = ow0 * stride - padding;

  for (int ic0 = 0; ic0 < in_per_group; ic0 += IC_T) {
    // Stage the input halo tile for IC_T channels.
    const int sX_elems = IC_T * SH * SW;
    for (int idx = tid; idx < sX_elems; idx += Threads) {
      const int ic_l = idx / (SH * SW);
      const int rem0 = idx - ic_l * (SH * SW);
      const int ih_l = rem0 / SW;
      const int iw_l = rem0 - ih_l * SW;

      const int c = ic_base + ic0 + ic_l;
      const int ih = base_ih + ih_l;
      const int iw = base_iw + iw_l;

      float v = 0.0f;
      if ((ic0 + ic_l) < in_per_group &&
          (unsigned)ih < (unsigned)H &&
          (unsigned)iw < (unsigned)Win) {
        v = (float)mX(c, ih, iw);
      }
      sX(ic_l, ih_l, iw_l) = v;
    }

    // Stage the matching weight tile: [OC_T, IC_T, KH, KW].
    const int sW_elems = OC_T * IC_T * KH * KW;
    for (int idx = tid; idx < sW_elems; idx += Threads) {
      const int kw = idx % KW;
      int rem = idx / KW;
      const int kh = rem % KH;
      rem /= KH;
      const int ic_l = rem % IC_T;
      const int oc_l = rem / IC_T;

      const int oc = oc0 + oc_l;
      float v = 0.0f;
      if (oc < oc_end && (ic0 + ic_l) < in_per_group) {
        v = (float)mW(oc, ic0 + ic_l, kh, kw);
      }
      sW(oc_l, ic_l, kh, kw) = v;
    }

    __syncthreads();

    if (valid_p) {
      const int ih_base_l = oh_l * stride;
      const int iw_base_l = ow_l * stride;

      for (int kh = 0; kh < KH; ++kh) {
        const int ih_l = ih_base_l + kh * dilation;
        for (int kw = 0; kw < KW; ++kw) {
          const int iw_l = iw_base_l + kw * dilation;

          #pragma unroll
          for (int ic_l = 0; ic_l < IC_T; ++ic_l) {
            const float xv = (float)sX(ic_l, ih_l, iw_l);
            #pragma unroll
            for (int oc_l = 0; oc_l < OC_T; ++oc_l) {
              acc[oc_l] += xv * (float)sW(oc_l, ic_l, kh, kw);
            }
          }
        }
      }
    }

    __syncthreads();
  }

  if (valid_p) {
    #pragma unroll
    for (int oc_l = 0; oc_l < OC_T; ++oc_l) {
      const int oc = oc0 + oc_l;
      if (oc < oc_end) {
        mY(oc, oh, ow) = acc[oc_l];
      }
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> bias,
                                  int64_t stride,
                                  int64_t padding,
                                  int64_t dilation,
                                  int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  TORCH_CHECK(w.dim() == 4, "w must be OIHW");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be positive");
  TORCH_CHECK(padding >= 0, "padding must be non-negative");
  TORCH_CHECK(groups > 0, "groups must be positive");

  const int64_t N = x.size(0);
  const int64_t C = x.size(1);
  const int64_t H = x.size(2);
  const int64_t Win = x.size(3);

  const int64_t OC = w.size(0);
  const int64_t C_per_g = w.size(1);
  const int64_t KH = w.size(2);
  const int64_t KW = w.size(3);

  TORCH_CHECK(C % groups == 0, "in_channels must be divisible by groups");
  TORCH_CHECK(OC % groups == 0, "out_channels must be divisible by groups");
  TORCH_CHECK(C_per_g == C / groups, "weight in_channels/groups mismatch");

  const int64_t in_per_group = C / groups;
  const int64_t out_per_group = OC / groups;

  const int64_t Hout = (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output spatial size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(b_c.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [out_channels]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int OH_T = 16;
  constexpr int OW_T = 16;
  constexpr int OC_T = 16;
  constexpr int IC_T = 16;

  const int64_t tiles_w = (Wout + OW_T - 1) / OW_T;
  const int64_t tiles_h = (Hout + OH_T - 1) / OH_T;
  const int64_t tiles_oc_per_group = (out_per_group + OC_T - 1) / OC_T;

  TORCH_CHECK(tiles_w * tiles_h <= 0x7fffffff, "too many spatial tiles");
  TORCH_CHECK(groups * tiles_oc_per_group <= 65535, "too many channel/group tiles");
  TORCH_CHECK(N <= 65535, "batch too large for this kernel grid");

  const int64_t SH = (OH_T - 1) * stride + (KH - 1) * dilation + 1;
  const int64_t SW = (OW_T - 1) * stride + (KW - 1) * dilation + 1;
  const size_t smem_bytes =
      (size_t)(IC_T * SH * SW + OC_T * IC_T * KH * KW) * sizeof(float);

  int max_smem = 0;
  cudaDeviceGetAttribute(&max_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, 0);
  TORCH_CHECK((int64_t)smem_bytes <= (int64_t)max_smem,
              "required dynamic shared memory exceeds device limit");

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(
        (const void*)conv2d_cute_tiled_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes
    );
  }

  dim3 block(Threads);
  dim3 grid(
      (unsigned)(tiles_w * tiles_h),
      (unsigned)(groups * tiles_oc_per_group),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_cute_tiled_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)KH, (int)KW,
      (int)Hout, (int)Wout,
      (int)stride, (int)padding, (int)dilation,
      (int)groups, (int)in_per_group, (int)out_per_group,
      (int)tiles_w, (int)tiles_oc_per_group
  );

  const auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
