class ModelNew(nn.Module):
    """
    Standard 2D convolution using one custom cooperative tiled CuTe/CUDA kernel.
    Parameters are stored in an nn.Conv2d-compatible module for initialization and
    state-dict compatibility, while forward() uses only the custom kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        self.use_bias = bool(bias)

        self.conv2d = nn.Conv2d(
            self.in_channels,
            self.out_channels,
            (self.kernel_size, self.kernel_size),
            stride=self.stride,
            padding=self.padding,
            dilation=self.dilation,
            groups=self.groups,
            bias=self.use_bias,
        )
        self._ext = _conv2d_cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x,
            self.conv2d.weight,
            self.conv2d.bias,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )
